from dataclasses import dataclass


@dataclass
class Item:
    price: float
    qty: int


def calc_total(items: list[Item], tax_rate: float) -> float:
    net = sum(i.price * i.qty for i in items)
    return net * (1 + tax_rate)


def format_price(amount: float) -> str:
    return f"${amount:.2f}"

